  // Secondary sequential-demo safeguard only. Static data is not an atomic lock.
  store.requests ??= {};
  store.authors ??= {};
  for (const collection of [store.requests, store.authors]) {
    for (const [key, timestamp] of Object.entries(collection)) if (now - timestamp > 86400000) delete collection[key];
  }
  const request = `request:${payload.request_id}`;
  const author = `author:${payload.author.author_id}`;
  if (Object.hasOwn(store.requests, request)) return { accepted: false, exact_duplicate: true, response_code: 200, error: '' };
  if (Object.hasOwn(store.authors, author) && now - store.authors[author] < 60000) return { accepted: false, exact_duplicate: false, response_code: 409, error: 'A summary was requested for this author moments ago. Retry later.' };
