  const short = parts.month.slice(0, 3);
  const candidates = [value.slice(0, 10), `${day} ${short} ${parts.year}`, `${day.padStart(2, '0')} ${short} ${parts.year}`, `${day} ${parts.month} ${parts.year}`, `${day.padStart(2, '0')} ${parts.month} ${parts.year}`];
