    const safe = {};
    // Explicit allowlist prevents arbitrary payload fields, headers, emails, or phone numbers reaching the model.
    for (const field of ['book_id', 'title', 'status', 'publication_date', 'last_royalty_payout_date', 'total_copies_sold', 'total_royalty_earned', 'royalty_paid', 'royalty_pending', 'available_on']) safe[field] = book[field];
    for (const field of ['isbn', 'genre', 'print_partner']) {
      if (book[field] !== undefined) {
        if (book[field] !== null && (typeof book[field] !== 'string' || book[field].length > 500)) return bad(`Invalid book.${field}`);
        safe[field] = book[field];
      }
    }
    for (const field of ['mrp', 'author_royalty_per_copy']) {
      if (book[field] !== undefined) {
        if (book[field] !== null && !amount(book[field])) return bad(`Invalid book.${field}`);
        safe[field] = book[field];
      }
    }
    safe.royalty_status = royaltyStatus(book, now);
    books.push(safe);
  }
  for (const [key, actual] of Object.entries(totals)) {
    if (payload.totals && (['earned', 'paid', 'pending'].includes(key) || payload.totals[key] !== undefined)) {
      if (!amount(payload.totals[key]) || !equal(actual, payload.totals[key])) return bad(`Payload totals.${key} does not match books`);
    }
  }
  const author = { author_id: payload.author.author_id, name: payload.author.name.trim() };
  for (const field of ['city', 'joined_date']) {
    if (payload.author[field] !== undefined && payload.author[field] !== null) {
      if (typeof payload.author[field] !== 'string' || payload.author[field].length > 200) return bad(`Invalid author.${field}`);
      author[field] = payload.author[field];
    }
  }
  return { valid: true, error: '', payload: { request_id: payload.request_id, author, books, totals, meta: { generated_at: new Date(now).toISOString(), source: 'bubble' } } };
}

function buildPromptData(payload, now = Date.now()) {
  const localParts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(now)).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
  const month = Number(localParts.month) - 1;
  const quarterEnd = new Date(Date.UTC(Number(localParts.year), Math.floor(month / 3) * 3 + 3, 0, 12));
  const payoutBy = new Date(quarterEnd.getTime() + 45 * 86400000);
  return {
    author: { ...payload.author, first_name: payload.author.name.split(/\s+/)[0] },
    books: payload.books,
    totals: payload.totals,
    policy: { cycle: 'quarterly', payment_window_days: 45, minimum_payout_inr: 1000, next_quarter_end: quarterEnd.toISOString().slice(0, 10), next_payout_by: payoutBy.toISOString().slice(0, 10), assessment_date: `${localParts.year}-${localParts.month}-${localParts.day}` },
    flags: { any_overdue: payload.books.some(book => book.royalty_status === 'Red'), all_paid: payload.totals.pending === 0, below_threshold: payload.totals.pending > 0 && payload.totals.pending < 1000, has_in_production: payload.books.some(book => book.royalty_status === 'In Production') },
  };
}

function guardRequest(store, payload, now = Date.now()) {
  // Secondary sequential-demo safeguard only. Static data is not an atomic lock.
  store.requests ??= {};
  store.authors ??= {};
  for (const collection of [store.requests, store.authors]) {
    for (const [key, timestamp] of Object.entries(collection)) if (now - timestamp > 86400000) delete collection[key];
  }
  const request = `request:${payload.request_id}`;
  const author = `author:${payload.author.author_id}`;
  if (Object.hasOwn(store.requests, request)) return { accepted: false, exact_duplicate: true, response_code: 200, error: '' };
  if (Object.hasOwn(store.authors, author) && now - store.authors[author] < 60000) return { accepted: false, exact_duplicate: false, response_code: 409, error: 'A summary was requested for this author moments ago. Retry later.' };
  store.requests[request] = now;
  store.authors[author] = now;
  return { accepted: true, exact_duplicate: false, response_code: 202, error: '' };
}

function textIncludesDate(text, value) {
  const date = new Date(royaltyDateInstant(value));
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'long', year: 'numeric' }).formatToParts(date).filter(part => part.type !== 'literal').map(part => [part.type, part.value]));
  const day = String(Number(parts.day));
  const short = parts.month.slice(0, 3);
  const candidates = [value.slice(0, 10), `${day} ${short} ${parts.year}`, `${day.padStart(2, '0')} ${short} ${parts.year}`, `${day} ${parts.month} ${parts.year}`, `${day.padStart(2, '0')} ${parts.month} ${parts.year}`];
  return candidates.some(candidate => text.toLowerCase().includes(candidate.toLowerCase()));
}

function parseSummary(response, promptData) {
  const fail = error => ({ valid: false, error });
  if (!isRecord(response) || response.error) return fail('AI provider request failed after retries');
  if (response.choices?.[0]?.finish_reason !== 'stop') return fail('AI output is incomplete');
  let content = response.choices?.[0]?.message?.content;
  if (typeof content !== 'string') return fail('AI provider returned no text');
  content = content.trim().replace(/^```(?:text)?\s*\n?/i, '').replace(/\n?```$/, '').trim();
  const parsed = /^SUBJECT:\s*([^\r\n]+)\s*\r?\n\s*BODY:\s*\r?\n?([\s\S]+)$/i.exec(content);
  if (!parsed) return fail('AI output must include SUBJECT and BODY');
  const subject = parsed[1].trim();
  const body = parsed[2].trim();
  if (!subject || subject.length > 80 || body.length < 200 || body.length > 5000) return fail('AI output length is outside the allowed range');
  if (/\{\{|\[Author|\[Book|\bTODO\b|As an AI|I cannot access|\bwebhook\b|\bn8n\b|\bAPI\b|\bprompt\b|\b(?:Red|Yellow|Green)\s*(?:badge|status|—)/i.test(body)) return fail('AI output contains a placeholder or internal language');
  if (/\b(?:payment|payout|transfer|bank transfer)\s+(?:is|has been|was)\s+(?:scheduled|processed|completed|sent)\b|\b(?:will|shall)\s+(?:be\s+)?(?:paid|transferred|deposited)\s+(?:tomorrow|on|by)\b|\b(?:transaction|bank|payment)\s+(?:id|reference)\s*[:#]/i.test(body)) return fail('AI output contains an unsupported payment promise or transaction reference');
  if (!body.toLowerCase().includes(promptData.author.first_name.toLowerCase())) return fail('AI output omits the author greeting');
  if (!body.includes('Team BookLeaf')) return fail('AI output omits the BookLeaf signature');
  if (promptData.flags.all_paid && /\boverdue\b/i.test(body)) return fail('Fully paid summary incorrectly describes overdue royalties');
  if (promptData.flags.any_overdue && !/48\s*(?:hours?|hrs?)|forty[- ]eight hours/i.test(body)) return fail('Overdue summary omits the 48-hour review');
  if (promptData.flags.below_threshold && (!/₹\s*1,?000\b/.test(body) || !/roll(?:s|ed|ing)?\s*over|rollover/i.test(body))) return fail('AI output omits the minimum payout threshold and rollover');
  if (!promptData.flags.all_paid && !promptData.flags.any_overdue) {
    if (!/quarter/i.test(body) || !/45\s*[- ]?\s*days?|forty[- ]five days/i.test(body) || !textIncludesDate(body, promptData.policy.next_quarter_end) || !textIncludesDate(body, promptData.policy.next_payout_by)) return fail('AI output omits the quarterly policy window');
  }
  for (const book of promptData.books) {
    if (!body.toLowerCase().includes(book.title.toLowerCase())) return fail('AI output omits a book');
    if (book.royalty_status === 'In Production' && !body.toLowerCase().includes(book.status.replace(/^In Production\s*-\s*/i, '').toLowerCase())) return fail('AI output omits a production stage');
    if (book.royalty_status !== 'In Production') {
      const begin = body.toLowerCase().indexOf(book.title.toLowerCase());
      const following = promptData.books.filter(other => other.book_id !== book.book_id).map(other => body.toLowerCase().indexOf(other.title.toLowerCase(), begin + book.title.length)).filter(index => index >= 0);
      const section = body.slice(begin + book.title.length, following.length ? Math.min(...following) : body.length);
      for (const [label, value] of [['earned', book.total_royalty_earned], ['paid', book.royalty_paid], ['pending', book.royalty_pending]]) {
        const match = new RegExp(`\\b${label}\\b[^₹\\n]{0,45}₹\\s*([\\d,]+(?:\\.\\d{1,2})?)`, 'i').exec(section);
        if (!match || Number(match[1].replaceAll(',', '')) !== value) return fail('AI output omits or misstates a per-book royalty figure');
      }
      if (!new RegExp(`(?:copies(?: sold)?|sold)\\s*[:=-]?\\s*${book.total_copies_sold}(?!\\d)|(?<!\\d)${book.total_copies_sold}\\s*copies`, 'i').test(section)) return fail('AI output omits or misstates copies sold');
      if (book.last_royalty_payout_date === null) {
        if (!/(?:no payout (?:ever )?(?:recorded|available)|no (?:royalty )?payment (?:recorded|yet)|not (?:available|recorded))/i.test(section)) return fail('AI output omits the absence of a payout date');
      } else {
        if (!textIncludesDate(section, book.last_royalty_payout_date)) return fail('AI output omits or misstates a last-payout date');
      }
    }
  }
  for (const label of ['earned', 'paid', 'pending']) if (!body.toLowerCase().includes(label)) return fail('AI output omits royalty totals');
  const mentioned = [...body.matchAll(/₹\s*([\d,]+(?:\.\d{1,2})?)/g)].map(match => Number(match[1].replaceAll(',', '')));
  const allowed = new Set([0, 1000, promptData.totals.earned, promptData.totals.paid, promptData.totals.pending]);
  for (const book of promptData.books) for (const field of ['total_royalty_earned', 'royalty_paid', 'royalty_pending']) allowed.add(book[field]);
  if (mentioned.some(value => !allowed.has(value))) return fail('AI output includes an unsupported monetary amount');
  for (const amount of [promptData.totals.earned, promptData.totals.paid, promptData.totals.pending]) if (!mentioned.includes(amount)) return fail('AI output omits a supplied total');
  const totalParagraphs = body.split(/\n\s*\n/).filter(paragraph => /\b(?:total|totals|across|overall|combined|consolidated)\b/i.test(paragraph) && /\bearned\b/i.test(paragraph) && /\b(?:paid|received)\b/i.test(paragraph) && /\bpending\b/i.test(paragraph));
  if (!totalParagraphs.length) return fail('AI output omits a clear consolidated totals section');
  const totalsSection = totalParagraphs[totalParagraphs.length - 1];
  for (const [label, pattern] of [['earned', 'earned'], ['paid', '(?:paid|received)'], ['pending', 'pending']]) {
    const match = new RegExp(`\\b${pattern}\\b[^₹\\n]{0,45}₹\\s*([\\d,]+(?:\\.\\d{1,2})?)`, 'i').exec(totalsSection);
    if (!match || Number(match[1].replaceAll(',', '')) !== promptData.totals[label]) return fail('AI output misstates a consolidated royalty total');
  }
  return { valid: true, error: '', summary_subject: subject, summary_body: body };
}


const input = $input.first().json;
let requestId = input.request_id;
if (!requestId) requestId = $('Build grounded prompt').first().json.request_id;
const safeReason = typeof input.error === 'string' && input.error.startsWith('AI output') ? input.error : 'AI generation failed after retries or failed validation. Check the n8n execution.';
return [{ json: { request_id: requestId, status: 'Failed', completed_at: new Date().toISOString(), summary_subject: '', summary_body: '', ai_model: MODEL, error_message: safeReason.slice(0, 1000), n8n_execution_id: String($execution.id) } }];
